    private func checkGreaterThanOrEqualToConstantB(_ value: H.Lane) {
        let mismatches = Mismatches("greaterThanOrEqualTo with b repeating \(hex(value))")
        let aInputs = Inputs.vectors(H.Vector.self, seed: 0x23AA_8109_F3F4_7B11)
        mismatches.check(
            H.repeating(value),
            HighwayReference.repeatingF16(value.bitPattern),
            "repeating"
        )
        for a in aInputs {
            mismatches.check(
                H.greaterThanOrEqualTo(a, H.repeating(value)),
                H.Mask(raw: HighwayReference.greaterThanOrEqualToF16(a, H.repeating(value))),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

